package apidserver

import (
	"net/http"

	"github.com/onebox-faas/faas/pkg/api"
)

func (s *server) registerOrgObjectRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageListSurface...)(s.object.ListBuckets))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.CreateBucket))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.DeleteBucket))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/access-grants", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ListBucketAccessGrants))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/access-grants/{key}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.SetBucketAccessGrant))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/access-grants/{key}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.DeleteBucketAccessGrant))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/s3-credentials", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ListObjectS3Credentials))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/s3-credentials", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.CreateObjectS3Credential))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/s3-credentials/{credential}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.RevokeObjectS3Credential))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/compute-bindings", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageBindingReadSurface...)(s.object.ListObjectStorageComputeBindings))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/compute-bindings", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.CreateObjectStorageComputeBinding))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/compute-bindings/{binding}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.DeleteObjectStorageComputeBinding))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/compute-bindings/{binding}/rotate", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.RotateObjectStorageComputeBinding))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageReadSurface...)(s.object.ListBucketObjects))))
	// Every other storage route with a reviewed organization permission
	// (authz.ObjectStorageAction), mirrored from /v1/apps/{slug}/... so company
	// apps are reachable under their organization (object storage audit OS-4).
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/upload-routes", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageListSurface...)(s.object.ListObjectUploadRoutes))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/upload-routes", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.CreateObjectUploadRoute))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/upload-routes/{route}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.DeleteObjectUploadRoute))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/s3-credentials/{credential}/copy-sources", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ListObjectS3CopySources))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/s3-credentials/{credential}/copy-sources/{source}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.SetObjectS3CopySource))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/s3-credentials/{credential}/copy-sources/{source}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.DeleteObjectS3CopySource))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.DeleteBucketObject))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/versions", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageReadSurface...)(s.object.ListBucketObjectVersions))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/versions", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.DeleteBucketObjectVersion))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/tags", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageReadSurface...)(s.object.ObjectBucketTags))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/tags", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.ObjectBucketTags))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/tags", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.ObjectBucketTags))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/deletions", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.CreateObjectDeletion))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/deletions/{deletion}", s.authLimited(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.GetObjectDeletion)))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/signed-url", s.authLimited(s.requireMFA(s.requireScope(api.ScopeAdmin, api.ScopeStorageRead, api.ScopeStorageWrite)(s.object.SignBucketObject))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/encryption-capabilities", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.GetObjectBucketEncryptionCapabilities))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/versioning", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.GetObjectBucketVersioning))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/object-lock-capabilities", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.GetObjectBucketObjectLockCapabilities))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/object-lock", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.GetObjectBucketObjectLock))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/object-lock", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.PutObjectBucketObjectLock))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/protection/retention", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectVersionRetention))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/protection/retention", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectVersionRetention))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/protection/legal-hold", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectVersionLegalHold))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/objects/protection/legal-hold", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectVersionLegalHold))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/protection-operations/{operation}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.GetVersionProtectionOperation))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/encryption", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.GetObjectBucketEncryption))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/encryption", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.PutObjectBucketEncryption))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/encryption", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.DeleteObjectBucketEncryption))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/versioning", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.PutObjectBucketVersioning))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/cors", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.GetObjectBucketCORS))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/cors", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.PutObjectBucketCORS))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/cors", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.DeleteObjectBucketCORS))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/lifecycle", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectBucketLifecycle))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/compute-triggers", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ReconcileObjectStorageComputeTriggers))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/notifications", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectBucketNotifications))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/notifications", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectBucketNotifications))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/notifications", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectBucketNotifications))))
	mux.HandleFunc("PUT /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/lifecycle", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectBucketLifecycle))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/lifecycle", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.ObjectBucketLifecycle))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/lifecycle/scans", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.CreateObjectLifecycleScan))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/lifecycle/scans/{scan}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageManageSurface...)(s.object.GetObjectLifecycleScan))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/capacity-reconciliations", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.CreateObjectCapacityReconciliation))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/write-receipts", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.ListObjectWriteReceipts))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/write-receipts/{receipt}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.GetObjectWriteReceipt))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/capacity-reconciliations/{reconciliation}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.GetObjectCapacityReconciliation))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/capacity-reconciliations/{reconciliation}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.CancelObjectCapacityReconciliation))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/multipart-uploads", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.ListObjectMultipartUploads))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/multipart-uploads", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.CreateObjectMultipartUpload))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/multipart-uploads/{upload}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.GetObjectMultipartUpload))))
	mux.HandleFunc("DELETE /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/multipart-uploads/{upload}", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.AbortObjectMultipartUpload))))
	mux.HandleFunc("GET /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/multipart-uploads/{upload}/parts", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.ListObjectMultipartParts))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/multipart-uploads/{upload}/parts/{part}/signed-url", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.SignObjectMultipartPart))))
	mux.HandleFunc("POST /v1/orgs/{organization}/apps/{slug}/buckets/{bucket}/multipart-uploads/{upload}/complete", s.authLimited(s.requireMFA(s.requireScope(api.ScopesStorageWriteSurface...)(s.object.CompleteObjectMultipartUpload))))
	mux.HandleFunc("GET /v1/orgs/{organization}/object-storage-usage", s.authLimited(s.requireMFA(s.requireScope(api.ScopesUsageReadSurface...)(s.object.GetObjectStorageUsage))))
}
